import re


def _norm_outcome(outcome):
    """Normalize outcome strings across API versions."""
    if outcome is None:
        return None
    o = str(outcome).strip().lower()
    mapping = {
        "approve": "approve",
        "approved": "approve",
        "decline": "decline",
        "declined": "decline",
        "refer": "refer",
        "manual_review": "refer",
        "manualreview": "refer",
    }
    return mapping.get(o)


def handle(app, svc):
    resp = svc.apply(app)
    if not isinstance(resp, dict):
        return {"action": "queue_review", "limit": 0}

    # API v2: {"api_version": 2, "result": {"outcome": ..., "credit_limit": ...}}
    # API v1: {"decision": ..., "limit": ...}
    if "result" in resp and isinstance(resp["result"], dict):
        result = resp["result"]
        outcome = result.get("outcome")
        credit_limit = result.get("credit_limit")
        if credit_limit is None:
            credit_limit = result.get("limit")
    else:
        outcome = resp.get("decision")
        credit_limit = resp.get("limit")

    outcome = _norm_outcome(outcome)

    if outcome is None:
        # Unknown outcome; do not decline, send to manual review.
        return {"action": "queue_review", "limit": 0}

    if outcome == "decline":
        return {"action": "decline", "limit": 0}

    if outcome == "refer":
        # Manual review per spec section 3 (do not decline).
        return {"action": "queue_review", "limit": 0}

    # outcome == "approve"
    try:
        limit = int(credit_limit)
    except (TypeError, ValueError):
        limit = 0

    # Network referral rule (all partners): a self_employed applicant whose
    # requested_limit is strictly above 6000 must go to manual review instead
    # of being issued. A decline stays a decline (handled above).
    employment = app.get("employment")
    if employment == "self_employed":
        try:
            requested = int(app.get("requested_limit"))
        except (TypeError, ValueError):
            requested = None
        if requested is not None and requested > 6000:
            return {"action": "queue_review", "limit": 0}

    return {"action": "issue", "limit": limit}

